const ovHtml=(H.length?`<div class="grid grid-cols-3 gap-2 mb-4"><div class="stat"><b>${H.length}</b><span>nawyków</span></div><div class="stat"><b>${tot}</b><span>wykonań (30 dni)</span></div><div class="stat"><b>${best[2]}</b><span>rekord w dzień</span></div></div><div class="card p-3 mb-4"><div class="text-sm text-muted mb-2">Ostatnie 26 tygodni (jaśniej = więcej zrobione)</div><div style="overflow-x:auto"><div style="display:grid;grid-auto-flow:column;grid-template-rows:repeat(7,12px);grid-auto-columns:12px;gap:3px">${'<i></i>'.repeat(pad)}${cells.map(c=>`<i title="${c[0]}: ${c[2]}" style="border-radius:3px;background:${c[2]?'var(--gold)':'var(--panel2)'};opacity:${c[2]?.3+c[1]*.7:1}"></i>`).join('')}</div></div></div><div class="card p-3 mb-4"><div class="flex items-center justify-between mb-2"><button class="btn btn-sm" data-x="calp" aria-label="Poprzedni miesiąc">←</button><b>${mname}</b><button class="btn btn-sm" data-x="caln" aria-label="Następny miesiąc">→</button></div><div style="display:grid;grid-template-columns:repeat(7,1fr);gap:3px">${'<i></i>'.repeat(cpad)}${ccells}</div></div><div class="card p-3"><div class="text-sm text-muted mb-2">Zrobione dni w ostatnich 30</div>${per.map(x=>`<div class="mb-2"><div class="flex justify-between text-sm"><span>${esc(x.n)}</span><b>${x.c}/30</b></div><div class="bar"><i style="width:${x.c/30*100}%"></i></div></div>`).join('')}</div>`:'<p class="text-muted">Dodaj nawyki i odhaczaj je, a tu pojawią się statystyki.</p>');
const tabs=[['ov','Przegląd'],['ch','Wykresy'],['nu','Liczby'],['fc','Fiszki']].map(([k,l])=>`<button class="btn btn-sm" data-x="stmode" data-i="${k}" aria-pressed="${stMode===k}" style="${stMode===k?'border-color:var(--gold)':''}">${l}</button>`).join('');
